/*
 * Fixed, trusted bridge between the native host and the bundled ag-psd codec.
 *
 * This file is part of the qualification package. It is not generated by a
 * model at runtime and it never evaluates model-authored JavaScript. The host
 * passes only base64-encoded PSD bytes and a JSON description of layer
 * metadata/pixels.
 *
 * The adapter configures ag-psd's canvas factory so that read useImageData and
 * write imageData paths work without a DOM or a real canvas. Any accidental
 * canvas access throws and is reported to the host.
 */
(function (global) {
  'use strict';

  if (!global.agPsd) {
    throw new Error('ag-psd bundle did not define the agPsd global');
  }
  var agPsd = global.agPsd;

  var factoryCalls = { canvas: 0, imageData: 0 };

  function fakeCanvas(width, height) {
    factoryCalls.canvas += 1;
    return {
      width: width,
      height: height,
      getContext: function () {
        throw new Error('ag-psd requested a real 2D canvas; the raw-ImageData path is mandatory');
      }
    };
  }

  function makeImageData(width, height) {
    factoryCalls.imageData += 1;
    return {
      width: width,
      height: height,
      data: new Uint8ClampedArray(width * height * 4)
    };
  }

  agPsd.initializeCanvas(fakeCanvas, makeImageData);

  var b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

  function base64Decode(text) {
    if (typeof text !== 'string') {
      throw new Error('base64 input is not a string');
    }
    var clean = text.replace(/\s+/g, '');
    if (clean.length % 4 === 1) {
      throw new Error('invalid base64 length');
    }
    var padding = 0;
    if (clean.slice(-2) === '==') padding = 2;
    else if (clean.slice(-1) === '=') padding = 1;
    clean = clean.replace(/=+$/, '');
    var out = new Uint8Array(Math.floor(clean.length * 3 / 4));
    var o = 0;
    for (var i = 0; i < clean.length; i += 4) {
      var a = b64chars.indexOf(clean.charAt(i));
      var b = i + 1 < clean.length ? b64chars.indexOf(clean.charAt(i + 1)) : 0;
      var c = i + 2 < clean.length ? b64chars.indexOf(clean.charAt(i + 2)) : 0;
      var d = i + 3 < clean.length ? b64chars.indexOf(clean.charAt(i + 3)) : 0;
      if (a < 0 || b < 0 || c < 0 || d < 0) {
        throw new Error('invalid base64 character');
      }
      var n = (a << 18) | (b << 12) | (c << 6) | d;
      if (o < out.length) out[o++] = (n >> 16) & 255;
      if (o < out.length) out[o++] = (n >> 8) & 255;
      if (o < out.length) out[o++] = n & 255;
    }
    if (padding > 0) {
      out = out.subarray(0, out.length);
    }
    return out;
  }

  function base64Encode(bytes) {
    var view = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    return agPsd.byteArrayToBase64(view);
  }

  function imageDataJSON(imageData) {
    if (!imageData) return null;
    return {
      width: imageData.width,
      height: imageData.height,
      data: base64Encode(imageData.data)
    };
  }

  function layerJSON(layer, includePixels) {
    var width = layer.imageData ? layer.imageData.width : 0;
    var height = layer.imageData ? layer.imageData.height : 0;
    var out = {
      name: layer.name || '',
      top: layer.top || 0,
      left: layer.left || 0,
      width: width,
      height: height,
      opacity: Math.round((typeof layer.opacity === 'number' ? layer.opacity : 1) * 255),
      hidden: !!layer.hidden,
      clipping: !!layer.clipping,
      transparencyProtected: !!layer.transparencyProtected,
      blendMode: layer.blendMode || 'normal',
      group: !!layer.children,
      childCount: layer.children ? layer.children.length : 0,
      hasText: !!layer.text,
      hasPlacedLayer: !!layer.placedLayer,
      hasAdjustment: !!layer.adjustment,
      hasEffects: !!layer.effects,
      hasVectorMask: !!layer.vectorMask,
      hasImageData: !!layer.imageData,
      mask: layer.mask ? {
        top: layer.mask.top || 0,
        left: layer.mask.left || 0,
        width: layer.mask.imageData ? layer.mask.imageData.width : 0,
        height: layer.mask.imageData ? layer.mask.imageData.height : 0,
        disabled: !!layer.mask.disabled,
        imageData: includePixels ? imageDataJSON(layer.mask.imageData) : null
      } : null
    };
    if (includePixels) {
      out.imageData = imageDataJSON(layer.imageData);
    }
    return out;
  }

  function collectLayers(layers, depth, out, includePixels) {
    var list = layers || [];
    for (var i = 0; i < list.length; i += 1) {
      var layer = list[i];
      var item = layerJSON(layer, includePixels);
      item.depth = depth;
      out.push(item);
      if (layer.children && layer.children.length) {
        collectLayers(layer.children, depth + 1, out, includePixels);
      }
    }
  }

  function readPsd(bytes, options) {
    var warnings = [];
    var psd = agPsd.readPsd(bytes, {
      useImageData: true,
      skipThumbnail: true,
      skipLinkedFilesData: true,
      logMissingFeatures: true,
      throwForMissingFeatures: false,
      totalMemoryLimit: options.totalMemoryLimit || 268435456,
      log: function (message) {
        warnings.push(String(message));
      }
    });
    var layers = [];
    collectLayers(psd.children || [], 0, layers, !!options.includePixels);
    return {
      ok: true,
      width: psd.width,
      height: psd.height,
      channels: psd.channels || 0,
      bitsPerChannel: psd.bitsPerChannel || 8,
      colorMode: psd.colorMode || 3,
      layers: layers,
      hasComposite: !!psd.imageData,
      composite: options.includeComposite ? imageDataJSON(psd.imageData) : null,
      warnings: warnings
    };
  }

  function buildImageData(json) {
    if (!json || !json.data) return undefined;
    var bytes = base64Decode(json.data);
    var expected = json.width * json.height * 4;
    if (bytes.length !== expected) {
      throw new Error('layer imageData has ' + bytes.length + ' bytes, expected ' + expected);
    }
    return {
      width: json.width,
      height: json.height,
      data: new Uint8ClampedArray(bytes.buffer, bytes.byteOffset, bytes.byteLength)
    };
  }

  function buildLayer(json) {
    var imageData = buildImageData(json.imageData);
    var layer = {
      name: json.name || '',
      top: json.top || 0,
      left: json.left || 0,
      opacity: (typeof json.opacity === 'number' ? json.opacity : 255) / 255,
      hidden: !!json.hidden,
      clipping: !!json.clipping,
      transparencyProtected: !!json.transparencyProtected,
      blendMode: json.blendMode || 'normal',
      imageData: imageData
    };
    if (json.mask && json.mask.imageData) {
      layer.mask = {
        top: json.mask.top || 0,
        left: json.mask.left || 0,
        disabled: !!json.mask.disabled,
        imageData: buildImageData(json.mask.imageData)
      };
    }
    return layer;
  }

  function writePsd(request) {
    var psd = {
      width: request.width,
      height: request.height,
      children: []
    };
    var layers = request.layers || [];
    for (var i = 0; i < layers.length; i += 1) {
      psd.children.push(buildLayer(layers[i]));
    }
    if (!request.composite || !request.composite.data) {
      throw new Error('a full composite imageData is required by ag-psd writePsd');
    }
    psd.imageData = buildImageData(request.composite);
    var bytes = agPsd.writePsdUint8Array(psd, {
      noBackground: true,
      logMissingFeatures: true,
      log: function () {}
    });
    return {
      ok: true,
      base64: base64Encode(bytes),
      byteLength: bytes.length,
      factoryCalls: { canvas: factoryCalls.canvas, imageData: factoryCalls.imageData }
    };
  }

  global.__floeReadPSD = function (base64, optionsJSON) {
    try {
      var options = optionsJSON ? JSON.parse(optionsJSON) : {};
      var bytes = base64Decode(base64);
      var result = readPsd(bytes, options);
      result.factoryCalls = { canvas: factoryCalls.canvas, imageData: factoryCalls.imageData };
      return JSON.stringify(result);
    } catch (error) {
      return JSON.stringify({ ok: false, error: String(error && error.message ? error.message : error) });
    }
  };

  global.__floeWritePSD = function (requestJSON) {
    try {
      var request = JSON.parse(requestJSON);
      var result = writePsd(request);
      return JSON.stringify(result);
    } catch (error) {
      return JSON.stringify({ ok: false, error: String(error && error.message ? error.message : error) });
    }
  };

  global.__floeRoundTrip = function (base64, optionsJSON) {
    try {
      var options = optionsJSON ? JSON.parse(optionsJSON) : {};
      var bytes = base64Decode(base64);
      var read = readPsd(bytes, { includePixels: true, includeComposite: true });
      var request = {
        width: read.width,
        height: read.height,
        layers: read.layers,
        composite: read.composite
      };
      var written = writePsd(request);
      return JSON.stringify({
        ok: true,
        base64: written.base64,
        byteLength: written.byteLength,
        layers: read.layers.length,
        factoryCalls: { canvas: factoryCalls.canvas, imageData: factoryCalls.imageData }
      });
    } catch (error) {
      return JSON.stringify({ ok: false, error: String(error && error.message ? error.message : error) });
    }
  };

  global.__floeCodecInfo = function () {
    return JSON.stringify({
      version: 'ag-psd-34.1.0',
      factoryCalls: { canvas: factoryCalls.canvas, imageData: factoryCalls.imageData }
    });
  };
})(typeof globalThis !== 'undefined' ? globalThis : this);
